mapper.select:
SELECT ROUND(sum(nvl(summary.t0kyxj,0)),2) AS T0KYXJ, /*T日可用现金*/ ROUND(sum(nvl(summary.t1kyxj,0)),2) AS T1KYXJ, /*T+1日可用现金*/ ROUND(sum(nvl(summary.AMOUNT,0)),2) AS ZHXJ, /*账户现金*/ ROUND(sum(nvl(summary.rrqmkdgh,0)),2) AS RRQMKDGHCC, /*融入券卖空待购回持仓*/ ROUND(sum(nvl(summary.zctrkycc,0)),2) AS ZCTRKYCC, /*资产T日可用持仓*/ ROUND(sum(nvl(summary.zct1rkycc,0)),2) AS ZCT1RKYCC, /*资产T+1日可用持仓*/ ROUND(sum(nvl(summary.bfqtrkycc,0)),2) AS BFQTRKYCC, /*本方券T日可用持仓*/ ROUND(sum(nvl(summary.bfqt1rkycc,0)),2) AS BFQT1RKYCC, /*本方券T+1日可用持仓*/ ROUND(sum(nvl(summary.rrqtrkycc,0)),2) AS RRQTRKYCC, /*融入券T日可用持仓*/ ROUND(sum(nvl(summary.rrqt1rkycc,0)),2) AS RRQT1RKYCC /*融入券T+1日可用持仓*/ FROM ( /*多组合，再汇总一遍*/ SELECT aa.t0kyxj, aa.t1kyxj, cc.AMOUNT, bb.rrqmkdgh, bb.zctrkycc, bb.zct1rkycc, bb.bfqtrkycc, bb.bfqt1rkycc, bb.rrqtrkycc, bb.rrqt1rkycc FROM( select a.PORTFOLIO_ID, sum( CASE WHEN b.S_HOLDINGTYPE=#{S_004} AND a.DATE_TYPE ='0' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS t0kyxj, /*T日可用现金*/ sum( CASE WHEN b.S_HOLDINGTYPE=#{S_004} AND a.DATE_TYPE ='1' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS t1kyxj /*T+1日可用现金*/ from ETR_CASH_POSITION_RULE a LEFT JOIN PTL_POSITION_CFG b ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE IN (#{S_004}) where to_char(a.cdate,'yyyy-MM-dd') = #{cdate} and b.S_HOLDINGTYPE IN (#{S_004})
AND a.PORTFOLIO_ID in
#{item}
GROUP BY a.PORTFOLIO_ID ) aa FULL OUTER JOIN ( select a.PORTFOLIO_ID, sum( CASE WHEN b.S_HOLDINGTYPE=#{S_003} THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS rrqmkdgh, /*融入券卖空待购回持仓*/ sum( CASE WHEN b.S_HOLDINGTYPE=#{S_001} AND a.DATE_TYPE ='0' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS zctrkycc, /*资产T日可用持仓*/ sum( CASE WHEN b.S_HOLDINGTYPE=#{S_001} AND a.DATE_TYPE ='1' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS zct1rkycc, /*资产T+1日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_004} AND a.DATE_TYPE ='0' THEN AMOUNT ELSE 0 END) AS bfqtrkycc, /*本方券T日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_004} AND a.DATE_TYPE ='1' THEN AMOUNT ELSE 0 END) AS bfqt1rkycc, /*本方券T+1日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_005} AND a.DATE_TYPE ='0' THEN AMOUNT ELSE 0 END) AS rrqtrkycc, /*融入券T日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_005} AND a.DATE_TYPE ='1' THEN AMOUNT ELSE 0 END) AS rrqt1rkycc /*融入券T+1日可用持仓*/ from ETR_SEC_POSITION_RULE a LEFT JOIN PTL_POSITION_CFG b ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE IN (#{S_001},#{S_003}) where to_char(a.cdate,'yyyy-MM-dd') = #{cdate} and (b.S_HOLDINGTYPE IN (#{S_001},#{S_003}) or a.HODING_TYPE in (#{A_004},#{A_005}))
and a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND a.PORTFOLIO_ID in
#{item}
GROUP BY a.PORTFOLIO_ID ) bb ON aa.PORTFOLIO_ID=bb.PORTFOLIO_ID LEFT JOIN (
SELECT d.PORTFOLIO_ID, sum(d.AMOUNT) AMOUNT FROM PTL_CASH_POSITION_RULE d where to_char(d.cdate,'yyyy-MM-dd') = #{cdate} AND d.HODING_TYPE =#{C_01}
and d.ACCT_ID = #{acctId,jdbcType=VARCHAR}
AND d.PORTFOLIO_ID in
#{item}
GROUP BY d.PORTFOLIO_ID ) cc ON nvl(aa.PORTFOLIO_ID, bb.PORTFOLIO_ID)=cc.PORTFOLIO_ID ) summary

SELECT ROUND(sum(nvl(summary.t0kyxj,0)),2) AS T0KYXJ, /*T日可用现金*/ ROUND(sum(nvl(summary.t1kyxj,0)),2) AS T1KYXJ, /*T+1日可用现金*/ ROUND(sum(nvl(summary.AMOUNT,0)),2) AS ZHXJ /*账户现金*/ FROM ( SELECT aa.t0kyxj, aa.t1kyxj, cc.AMOUNT FROM( select a.PORTFOLIO_ID, sum( CASE WHEN b.S_HOLDINGTYPE=#{S_004} AND a.DATE_TYPE ='0' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS t0kyxj, /*T日可用现金*/ sum( CASE WHEN b.S_HOLDINGTYPE=#{S_004} AND a.DATE_TYPE ='1' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS t1kyxj /*T+1日可用现金*/ from ETR_CASH_POSITION_RULE a LEFT JOIN PTL_POSITION_CFG b ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE IN (#{S_004}) where a.cdate = to_date(#{cdate},'yyyy-MM-dd') and b.S_HOLDINGTYPE IN (#{S_004})
AND a.PORTFOLIO_ID in
#{item}
GROUP BY a.PORTFOLIO_ID ) aa LEFT JOIN (
SELECT d.PORTFOLIO_ID, sum(d.AMOUNT) AMOUNT FROM PTL_CASH_POSITION_RULE d where d.cdate = to_date(#{cdate},'yyyy-MM-dd') AND d.HODING_TYPE =#{C_01}
and d.ACCT_ID = #{acctId,jdbcType=VARCHAR}
AND d.PORTFOLIO_ID in
#{item}
GROUP BY d.PORTFOLIO_ID ) cc ON aa.PORTFOLIO_ID=cc.PORTFOLIO_ID ) summary

SELECT
ROUND(sum(nvl(aa.T0KYXJ,0)),2) AS T0KYXJ,       /*T日可用现金*/
ROUND(sum(nvl(aa.T1KYXJ,0)),2) AS T1KYXJ,       /*T+1日可用现金*/
ROUND(sum(nvl(aa.ZHXJ,0)),2) AS ZHXJ          /*账户现金*/
FROM(
    select
    a.PORTFOLIO_ID,
    sum(
        CASE WHEN b.S_HOLDINGTYPE=#{S_004} AND a.DATE_TYPE ='0' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END
    ) AS T0KYXJ, /*T日可用现金*/
    sum(
        CASE WHEN b.S_HOLDINGTYPE=#{S_004} AND a.DATE_TYPE ='1' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END
    ) AS T1KYXJ, /*T+1日可用现金*/
    sum(
        CASE WHEN a.HODING_TYPE=#{C_01} THEN a.AMOUNT ELSE 0 END
    ) AS ZHXJ   /*账户现金*/
    from PTL_CASH_POSITION_RULE a
    LEFT JOIN PTL_POSITION_CFG b ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE IN (#{S_004})
    where a.cdate = to_date(#{cdate},'yyyy-MM-dd') and b.S_HOLDINGTYPE IN (#{S_004}, #{C_01})

        and a.ACCT_ID = #{acctId,jdbcType=VARCHAR}


        and a.ACCT_ID in (
            SELECT ACCT_NO from PTL_CAPACCT_INFO where PORTFOLIO_ID in

                #{item}

            and ACCT_TYPE in

                #{item}

        )


        AND a.PORTFOLIO_ID in

            #{item}


    GROUP BY a.PORTFOLIO_ID
) aa

select a.PORTFOLIO_ID, sum( CASE WHEN b.S_HOLDINGTYPE=#{S_003} THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS RRQMKDGH, /*融入券卖空待购回持仓*/ sum( CASE WHEN b.S_HOLDINGTYPE=#{S_001} AND a.DATE_TYPE ='0' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS ZCTRKYCC, /*资产T日可用持仓*/ sum( CASE WHEN b.S_HOLDINGTYPE=#{S_001} AND a.DATE_TYPE ='1' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS ZCT1RKYCC, /*资产T+1日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_004} AND a.DATE_TYPE ='0' THEN AMOUNT ELSE 0 END) AS BFQTRKYCC, /*本方券T日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_004} AND a.DATE_TYPE ='1' THEN AMOUNT ELSE 0 END) AS BFQT1RKYCC, /*本方券T+1日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_005} AND a.DATE_TYPE ='0' THEN AMOUNT ELSE 0 END) AS RRQTRKYCC, /*融入券T日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_005} AND a.DATE_TYPE ='1' THEN AMOUNT ELSE 0 END) AS RRQT1RKYCC /*融入券T+1日可用持仓*/ from ETR_SEC_POSITION_RULE a LEFT JOIN PTL_POSITION_CFG b ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE IN (#{S_001},#{S_003}) where a.cdate = to_date(#{cdate},'yyyy-MM-dd') and (b.S_HOLDINGTYPE IN (#{S_001},#{S_003}) or a.HODING_TYPE in (#{A_004},#{A_005}))
and a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND a.PORTFOLIO_ID in
#{item}
GROUP BY a.PORTFOLIO_ID

select a.PORTFOLIO_ID, sum( CASE WHEN b.S_HOLDINGTYPE=#{S_003} THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS RRQMKDGH, /*融入券卖空待购回持仓*/ sum( CASE WHEN b.S_HOLDINGTYPE=#{S_005} AND a.DATE_TYPE ='0' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS ZCTRKYCC, /*资产T日可用持仓*/ sum( CASE WHEN b.S_HOLDINGTYPE=#{S_005} AND a.DATE_TYPE ='1' THEN a.AMOUNT*nvl(b.CAL_FLAG,1) ELSE 0 END ) AS ZCT1RKYCC, /*资产T+1日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_004} AND a.DATE_TYPE ='0' THEN AMOUNT ELSE 0 END) AS BFQTRKYCC, /*本方券T日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_004} AND a.DATE_TYPE ='1' THEN AMOUNT ELSE 0 END) AS BFQT1RKYCC, /*本方券T+1日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_005} AND a.DATE_TYPE ='0' THEN AMOUNT ELSE 0 END) AS RRQTRKYCC, /*融入券T日可用持仓*/ sum(CASE WHEN a.HODING_TYPE=#{A_005} AND a.DATE_TYPE ='1' THEN AMOUNT ELSE 0 END) AS RRQT1RKYCC /*融入券T+1日可用持仓*/ from PTL_SEC_POSITION_RULE a LEFT JOIN PTL_POSITION_CFG b ON a.HODING_TYPE =b.HOLDINGTYPE AND b.S_HOLDINGTYPE IN (#{S_005},#{S_003}) where a.cdate = to_date(#{cdate},'yyyy-MM-dd') and (b.S_HOLDINGTYPE IN (#{S_005},#{S_003}) or a.HODING_TYPE in (#{A_004},#{A_005}))
and a.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND a.PORTFOLIO_ID in
#{item}
GROUP BY a.PORTFOLIO_ID
